function drawPlantText(guiGraphics, text, x, y, maxWidth, defaultColor) {
  guiGraphics.drawWordWrap(Client.font, text, x, y, maxWidth, defaultColor || 0x202020);
}

function getValidPlantItems(entry) {
  let out = [];
  let list = entry.items || [];
  for (let i = 0; i < list.length; i++) {
    let st = Item.of(list[i]);
    if (st && !st.isEmpty()) {
      out.push(list[i]);
    }
  }
  return out;
}

function formatPlantTagComponent(entry) {
  if (entry.tagKey === "specific") {
    return Text.translatable("jei.better_sunlit.plant.tag.specific", `${entry.biomes.length}`);
  }
  return Text.translatable(entry.tagKey);
}

function buildBiomePreviewLine(biomes, startIdx, maxItems) {
  let acc = Text.empty();
  let end = Math.min(biomes.length, startIdx + maxItems);
  for (let i = startIdx; i < end; i++) {
    if (i > startIdx) acc = acc.append(Text.of(", "));
    let bid = biomes[i];
    let tkey = "biome." + bid.replace(":", ".");
    acc = acc.append(Text.translatable(tkey));
  }
  return acc;
}

function renderPlantHabitatCard(data, guiGraphics) {
  let validItems = data.validItems || data.items || [];
  let isGroup = validItems.length > 4;
  let headWidth = isGroup ? 170 : Math.max(96, 170 - validItems.length * 19);

  drawPlantText(guiGraphics, Text.translatable(data.kindKey).darkGray(), 3, 2, headWidth, 0x404040);
  if (validItems.length > 0) {
    drawPlantText(guiGraphics, Item.of(validItems[0]).hoverName, 3, 12, headWidth, 0x101010);
  }

  let bodyY = isGroup ? 66 : 28;
  drawPlantText(guiGraphics, Text.translatable(data.dimKey).darkGreen(), 3, bodyY, 170, 0x202020);
  bodyY += 11;

  drawPlantText(
    guiGraphics,
    Text.translatable("jei.better_sunlit.plant.tag_label", formatPlantTagComponent(data).darkBlue()),
    3,
    bodyY,
    170,
    0x202020
  );
  bodyY += 12;

  let biomes = data.biomes || [];
  if (!isGroup) {
    drawPlantText(guiGraphics, Text.translatable("jei.better_sunlit.plant.biomes_header").darkGray(), 3, bodyY, 170, 0x303030);
    bodyY += 10;
    let previewLimit = Math.min(biomes.length, 6);
    let preview = buildBiomePreviewLine(biomes, 0, previewLimit);
    if (biomes.length > previewLimit) {
      preview = preview.append(Text.of(" ")).append(
        Text.translatable("jei.better_sunlit.plant.more_biomes", `${biomes.length - previewLimit}`).darkGray()
      );
    }
    drawPlantText(guiGraphics, preview, 4, bodyY, 168, 0x181818);
    bodyY += 32;
  }

  if (bodyY <= 108) {
    drawPlantText(guiGraphics, Text.translatable(data.noteKey).gold(), 3, bodyY, 170, 0x303030);
  }

  drawPlantText(
    guiGraphics,
    Text.translatable("jei.better_sunlit.plant.hover_hint").darkGray(),
    3,
    120,
    170,
    0x555555
  );
}

function buildPlantTooltipLines(data) {
  let lines = [];
  lines.push(Text.translatable(data.dimKey).green());
  lines.push(Text.translatable("jei.better_sunlit.plant.tag_label", formatPlantTagComponent(data).aqua()));
  lines.push(Text.translatable("jei.better_sunlit.plant.biomes_header").yellow());

  let biomes = data.biomes || [];
  let maxShown = Math.min(biomes.length, 24);
  for (let i = 0; i < maxShown; i += 3) {
    let row = Text.of("• ").gray().append(buildBiomePreviewLine(biomes, i, 3)).white();
    lines.push(row);
  }
  if (biomes.length > maxShown) {
    lines.push(
      Text.translatable("jei.better_sunlit.plant.more_biomes", `${biomes.length - maxShown}`).gray()
    );
  }
  lines.push(Text.translatable(data.noteKey).gold());
  lines.push(Text.translatable("jei.better_sunlit.plant.note.compass").gray());
  return lines;
}

JEIAddedEvents.registerCategories((e) => {
  let guiHelper = e.data.jeiHelpers.guiHelper;
  e.custom("society:wild_plants", (category) => {
    category
      .title(Text.translatable("jei.better_sunlit.plant.category"))
      .background(guiHelper.createBlankDrawable(176, 132))
      .icon(guiHelper.createDrawableItemStack(Item.of("minecraft:flowering_azalea")))
      .isRecipeHandled((recipe) => {
        return !!(recipe?.data?.items !== undefined && recipe?.data?.biomes !== undefined);
      })
      .setDrawHandler((recipe, recipeSlotsView, guiGraphics) => {
        renderPlantHabitatCard(recipe.getRecipeData(), guiGraphics);
      })
      .handleLookup((builder, recipe) => {
        let data = recipe.data;
        let validItems = data.validItems || data.items || [];
        let isGroup = validItems.length > 4;

        if (isGroup) {
          for (let i = 0; i < validItems.length && i < 16; i++) {
            let gx = 4 + (i % 8) * 21;
            let gy = 24 + Math.floor(i / 8) * 19;
            builder
              .addSlot("OUTPUT", gx, gy)
              .addItemStack(Item.of(validItems[i]))
              .addTooltipCallback((slotView, tooltip) => {
                let tipLines = buildPlantTooltipLines(data);
                tipLines.forEach((line, idx) => {
                  tooltip.add(idx + 1, line);
                });
              })
              .setBackground(guiHelper.getSlotDrawable(), -1, -1);
          }
        } else {
          for (let j = 0; j < validItems.length && j < 4; j++) {
            let sx = 156 - j * 19;
            builder
              .addSlot("OUTPUT", sx, 2)
              .addItemStack(Item.of(validItems[j]))
              .addTooltipCallback((slotView, tooltip) => {
                let tipLines = buildPlantTooltipLines(data);
                tipLines.forEach((line, idx) => {
                  tooltip.add(idx + 1, line);
                });
              })
              .setBackground(guiHelper.getSlotDrawable(), -1, -1);
          }
        }
      });
  });
});

JEIAddedEvents.registerRecipes((e) => {
  PLANT_HABITATS.forEach((entry) => {
    let valid = getValidPlantItems(entry);
    if (valid.length === 0) return;
    e.custom("society:wild_plants").add({
      items: entry.items,
      validItems: valid,
      dimKey: entry.dimKey,
      kindKey: entry.kindKey,
      tagKey: entry.tagKey,
      noteKey: entry.noteKey,
      biomes: entry.biomes,
    });
  });
});
